import { useState } from "react";
import { useNavigate } from "react-router-dom";

const KycDetails = () => {
  const navigate = useNavigate();

  const [formData, setFormData] = useState({
    aadhaar: {
      aadhaarNumber: "",
      name: "",
      dateOfBirth: "",
      document: ""
    },
    pan: {
      panNumber: "",
      name: "",
      document: ""
    }
  });
  const [selectedFile, setSelectedFile] = useState(null);

  const handleAadhaarChange = (e) => {
    const { name, value } = e.target;

    if (name === "aadhaarNumber" && !/^[0-9]*$/.test(value)) {
      return;
    }
    if (name === "name") {
      if (!/^[A-Za-z ]*$/.test(value)) {
        return;
      }
    }

    setFormData({
      ...formData,
      aadhaar: {
        ...formData.aadhaar,
        [name]: value
      }
    });
  };

  const handlePanChange = (e) => {
    const { name, value } = e.target;

    if (name === "name") {
      if (!/^[A-Za-z ]*$/.test(value)) {
        return;
      }
    }

    setFormData({
      ...formData,
      pan: {
        ...formData.pan,
        [name]: value.toUpperCase()
      }
    });
  };

  const handleSave = () => {
    fetch("http://localhost:5000/userProfile", {
      method: "PATCH",
      headers: {
        "Content-Type": "application/json"
      },
      body: JSON.stringify({
        kycDetails: formData
      })
    })
      .then((response) => response.json())
      .then(() => {
        alert("KYC details saved successfully");
        navigate("/gst-details");
      })
      .catch((error) => {
        console.log(error);
        alert("Error saving KYC details");
      });
  };
  const handleDocumentChange = (e) => {
    const file = e.target.files[0];

    if (!file) {
      return;
    }

    // Store the actual file temporarily
    setSelectedFile(file);

    // Store only the filename in formData
    setFormData({
      ...formData,
      pan: {
        ...formData.pan,
        document: file.name
      }
    });
  };

  const handleDownload = () => {
    if (!selectedFile) {
      return;
    }

    const fileUrl = URL.createObjectURL(selectedFile);

    const link = document.createElement("a");

    link.href = fileUrl;
    link.download = selectedFile.name;

    document.body.appendChild(link);

    link.click();

    document.body.removeChild(link);

    URL.revokeObjectURL(fileUrl);
  };



  return (
    <div className="form-card">
      <div className="form-header">
        <h2>Aadhaar & PAN Details</h2>
        <p>Enter your Aadhaar and PAN details</p>
      </div>

      <div className="kyc-cards">

        {/* Aadhaar */}
        <div className="kyc-card">
          <h3>Aadhaar Details</h3>

          <div className="form-group">
            <label>Aadhaar Number</label>
            <input
              type="text"
              name="aadhaarNumber"
              placeholder="Enter Aadhaar number"
              maxLength="12"
              inputMode="numeric"
              value={formData.aadhaar.aadhaarNumber}
              onChange={handleAadhaarChange}
            />
          </div>

          <div className="form-group">
            <label>Name as per Aadhaar</label>
            <input
              type="text"
              name="name"
              placeholder="Enter name"
              value={formData.aadhaar.name}
              onChange={handleAadhaarChange}
              pattern="[A-Za-z ]+"
            />
          </div>

          <div className="form-group">
            <label>Date of Birth</label>
            <input
              type="date"
              name="dateOfBirth"
              value={formData.aadhaar.dateOfBirth}
              onChange={handleAadhaarChange}
            />
          </div>
          <div className="form-group">
            <label>Aadhar Document</label>

            <input
              type="file"
              accept=".pdf,.jpg,.jpeg,.png"
              onChange={handleDocumentChange}
            />

            {selectedFile && (
              <button
                type="button"
                className="file-name-button"
                onClick={handleDownload}
              >
                {selectedFile.name}
              </button>
            )}
          </div>
        </div>

        {/* PAN */}
        <div className="kyc-card">
          <h3>PAN Details</h3>

          <div className="form-group">
            <label>PAN Number</label>
            <input
              type="text"
              name="panNumber"
              placeholder="Enter PAN number"
              maxLength="10"
              pattern="[A-Z-z1-9]+"
              value={formData.pan.panNumber}
              onChange={handlePanChange}
            />
          </div>

          <div className="form-group">
            <label>Name as per PAN</label>
            <input
              type="text"
              name="name"
              placeholder="Enter name"
              value={formData.pan.name}
              onChange={handlePanChange}
              pattern="[A-Za-z ]+"
            />
          </div>

          <div className="form-group">
            <label>PAN Document</label>

            <input
              type="file"
              accept=".pdf,.jpg,.jpeg,.png"
              onChange={handleDocumentChange}
            />

            {selectedFile && (
              <button
                type="button"
                className="file-name-button"
                onClick={handleDownload}
              >
                {selectedFile.name}
              </button>
            )}
          </div>
        </div>

      </div>

      <div className="form-footer">
        <button
          className="save-button"
          onClick={handleSave}
        >
          Save KYC Details
        </button>
      </div>
    </div>
  );
};

export default KycDetails;
